INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (0.0, 4, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 24, 1, 110501, 24015, 0.0, "カオリ（サマー）", 10021, 4);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (4.0, 4, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 24, 2, 110501, 24016, 0.0, "カオリ（サマー）", 10021, 1);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (0.0, 4, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "マジムンだらけで目が回るさ～！\nふらふらさ～！", 24, 3, 110501, 24017, 0.0, "カオリ（サマー）", 10021, 4);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (5.2, 1, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 24, 4, 110501, 24018, 0.0, "カオリ（サマー）", 10021, 2);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (4.2, 5, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 24, 5, 110501, 24019, 0.0, "カオリ（サマー）", 10021, 6);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (0.0, 2, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 24, 6, 110501, 24020, 0.0, "カオリ（サマー）", 10021, 2);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (6.4, 1, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 24, 7, 110501, 24021, 0.0, "カオリ（サマー）", 10021, 6);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (0.0, 2, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 24, 8, 110501, 24022, 0.0, "カオリ（サマー）", 10021, 2);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (10.08, 6, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 24, 9, 110501, 24023, 0.0, "カオリ（サマー）", 10021, 3);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (5.0, 1, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 24, 10, 110501, 24024, 0.0, "カオリ（サマー）", 10021, 2);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (0.0, 2, "2030/12/17 14:59:59", "2019/07/31 12:00:00", 0.0, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 24, 11, 110501, 24025, 0.0, "カオリ（サマー）", 10021, 2);
